contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address logAddr, uint marker) public payable {
        // Fresh contract: set a marker value that can be observed via the public MinSum getter.
        c.SetMinSum(marker); if (__ESBMC_reverted()) return;
        uint before = c.MinSum(); if (__ESBMC_reverted()) return;

        // First SetLogFile on an uninitialized contract: must complete and leave MinSum unchanged.
        bool firstOk;
        c.SetLogFile(logAddr); bool __rev0 = __ESBMC_reverted(); if (__rev0) { firstOk = false; } else { firstOk = true; }
        uint afterFirst = c.MinSum(); if (__ESBMC_reverted()) return;

        // Second SetLogFile before initialization: must also complete and leave MinSum unchanged.
        bool secondOk;
        c.SetLogFile(address(this)); bool __rev1 = __ESBMC_reverted(); if (__rev1) { secondOk = false; } else { secondOk = true; }
        uint afterSecond = c.MinSum(); if (__ESBMC_reverted()) return;

        // General rule: on a fresh, uninitialized contract every SetLogFile succeeds and does not
        // alter the publicly observable MinSum value.
        assert(firstOk && secondOk && afterFirst == before && afterSecond == before);
    }
}

