pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(address logAddr, uint256 marker) internal {
        try c.SetMinSum(marker) {} catch { return; }
        uint256 before;
        try c.MinSum() returns (uint256 __r) { before = __r; } catch { return; }
        bool firstOk;
        try c.SetLogFile(logAddr) { firstOk = true; } catch { firstOk = false; }
        uint256 afterFirst;
        try c.MinSum() returns (uint256 __r) { afterFirst = __r; } catch { return; }
        bool secondOk;
        try c.SetLogFile(address(this)) { secondOk = true; } catch { secondOk = false; }
        uint256 afterSecond;
        try c.MinSum() returns (uint256 __r) { afterSecond = __r; } catch { return; }
        assertTrue(firstOk && secondOk && afterFirst == before && afterSecond == before);
    }

    function testFuzz_run(address logAddr, uint256 marker) public {
